pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(putAmount > 0 && putAmount <= 100 ether);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);

        // Setup: put some ether into the contract for caller
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Record pre-collect balance of caller and contract
        uint preCallerBal = caller.balance;
        uint preContractBal = address(c).balance;

        // Try to collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // The invariant: if Collect succeeded, caller's balance increase must equal collectAmount
        // AND contract balance decrease must equal collectAmount
        if (success) {
            uint postCallerBal = caller.balance;
            uint postContractBal = address(c).balance;

            // General rule: caller gains exactly collectAmount, contract loses exactly collectAmount
            assertTrue(
                postCallerBal == preCallerBal + collectAmount &&
                postContractBal == preContractBal - collectAmount,
                "Collect successful but balances changed incorrectly"
            );
        } else {
            // No revert check needed; just ensure the invariant holds vacuously
            assertTrue(true);
        }
    }
}

