        // Call Put from sender
        vm.prank(sender);
        c.Put(unlockTime);

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(sender).balance;

        // Compute a withdrawal amount (can be random, but we need to test both valid and invalid withdraws)
        uint256 withdrawAmount = bound(uint256(keccak256(abi.encode(timeOffset))), 0, 2 * balanceBefore);

        // Set block timestamp to be after or before unlockTime based on timeOffset
        uint256 currentTime = bound(timeOffset, 1, type(uint256).max - 1);
        vm.warp(currentTime);

        // Make Collect call
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // Record balance after Collect
        uint256 balanceAfter = c.Acc(sender).balance;

        // Determine expected behavior based on conditions
        bool timeCondition = currentTime > c.Acc(sender).unlockTime; // Note: unlockTime was set by Put, but M might not update it; the reference C updates it correctly
        // Actually, for the reference, unlockTime is stored; for mutant, it's not set. So we use the reference condition.
        // We need to check if the Collect call should have succeeded according to the contract logic.
        bool validWithdraw = (balanceBefore >= c.MinSum()) && (balanceBefore >= withdrawAmount) && (currentTime > c.Acc(sender).unlockTime);

        if (success) {
            // If Collect succeeded, balance decreased by withdrawAmount
            assertTrue(balanceBefore - balanceAfter == withdrawAmount, "Balance should decrease by withdrawn amount on success");
        } else {
            // If Collect reverted, balance unchanged
            assertTrue(balanceBefore == balanceAfter, "Balance should remain unchanged on revert");
        }
    }
}

