        // Record sum of all balances before Collect attempt
        uint256 sumBefore = c.Acc(sender).balance; // public getter

        // Attempt Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Sum after Collect
        uint256 sumAfter = c.Acc(sender).balance;

        // Rule: if Collect reverted, sum must not decrease
        assertTrue(!success || sumAfter == sumBefore - collectAmount);
    }
}

