contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);

        // Set the block timestamp to a fixed value for determinism
        vm.warp(1000);

        // Ensure unlockTime equals current block.timestamp
        vm.assume(unlockTime == 1000);

        // Fund the caller and call Put to add balance
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Ensure balance is at least MinSum and collectAmount
        uint256 minSum = c.MinSum();
        vm.assume(c.Acc(caller).balance >= minSum);
        vm.assume(c.Acc(caller).balance >= collectAmount);

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(caller).balance;

        // Call Collect when block.timestamp == unlockTime
        address cAddress = address(c);
        (bool ok,) = cAddress.call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Rule: balance must not decrease if collect succeeded (which should not happen in reference)
        uint256 balanceAfter = c.Acc(caller).balance;
        // In reference, Collect should revert when timestamp == unlockTime, so balance unchanged
        // In mutant, Collect may succeed and decrease balance; this breaks the rule
        assertTrue(balanceAfter >= balanceBefore);
    }
